  console.log('=== Processing Item ===');
  console.log('Available fields:', Object.keys(data));

  // Extract uploaded photo - try multiple possible field names
  let imageBase64 = '';
  let imageData = data.headshot_photo || data.headshotPhoto || data.uploaded_photo || data.image;

  console.log('Image field type:', typeof imageData);

  if (!imageData) {
    throw new Error('No image data found. Available fields: ' + Object.keys(data).join(', '));
  }

  // Handle different data formats
  if (typeof imageData === 'string') {
    console.log('Image is string, length:', imageData.length);
    // Remove data URL prefix if present
    if (imageData.includes('base64,')) {
      imageBase64 = imageData.split('base64,')[1];
    } else if (imageData.startsWith('data:')) {
      imageBase64 = imageData.split(',')[1] || imageData;
    } else {
      imageBase64 = imageData;
    }
  } else if (typeof imageData === 'object' && imageData !== null) {
    console.log('Image is object with keys:', Object.keys(imageData));

    // Try various property names
    if (imageData.data) {
      imageBase64 = typeof imageData.data === 'string' ? imageData.data : Buffer.from(imageData.data).toString('base64');
    } else if (imageData.base64) {
      imageBase64 = imageData.base64;
    } else if (imageData.content) {
      imageBase64 = imageData.content;
    } else if (imageData.buffer) {
      imageBase64 = Buffer.from(imageData.buffer).toString('base64');
    } else if (Array.isArray(imageData)) {
      // Handle array buffer
      imageBase64 = Buffer.from(imageData).toString('base64');
    } else {
      throw new Error('Image object structure not recognized. Keys: ' + Object.keys(imageData).join(', '));
    }
  } else {
    throw new Error('Unexpected image data type: ' + typeof imageData);
  }

  // Clean up base64 string
  imageBase64 = imageBase64.replace(/^data:image\/\w+;base64,/, '').trim();

  if (!imageBase64 || imageBase64.length < 100) {
    throw new Error('Image data is empty or too short after processing');
  }

  console.log('✅ Successfully extracted base64, length:', imageBase64.length);

  processedItems.push({
    json: {
