// This node's job is to find and extract a JSON object from the raw text output of the AI.
// This is much more robust than the strict Structured Output Parser.

const items = $input.all();
const extractedData = [];

for (const item of items) {
  // Get the raw text from the AI Agent's output
  const rawText = item.json.output;

  if (typeof rawText !== 'string') {
    console.log('Input was not a string, skipping.');
    continue;
  }

  // Find the start and end of the JSON object
  const startIndex = rawText.indexOf('{');
  const endIndex = rawText.lastIndexOf('}');

  if (startIndex === -1 || endIndex === -1) {
    throw new Error("Could not find a valid JSON object in the AI's response.");
  }

  // Extract the JSON string
  const jsonString = rawText.substring(startIndex, endIndex + 1);

  try {
    // Parse the extracted string into a real JSON object
    const parsedJson = JSON.parse(jsonString);
    extractedData.push({ json: parsedJson });
  } catch (error) {
    throw new Error("Failed to parse the extracted JSON. Error: " + error.message);
  }
}

return extractedData;

