  // Handle different response structures
  let images = [];

  // Robustly check for Gemini response structure.
  if (response.candidates && Array.isArray(response.candidates)) {
    images = response.candidates.flatMap(candidate => 
        (candidate.content && Array.isArray(candidate.content.parts))
            ? candidate.content.parts
                .filter(part => part.inlineData && part.inlineData.data)
                .map(part => part.inlineData.data)
            : []
    );
  } 

  // Fallback for other potential API structures
  else if (response.modelOutputs && response.modelOutputs.images) {
    images = Array.isArray(response.modelOutputs.images) 
      ? response.modelOutputs.images 
      : [response.modelOutputs.images];
  } else if (response.outputs && response.outputs.images) {
    images = Array.isArray(response.outputs.images) 
      ? response.outputs.images 
      : [response.outputs.images];
  } else if (response.images) {
    images = Array.isArray(response.images) 
      ? response.images 
      : [response.images];
  } else if (response.image) {
    images = [response.image];
  }

  // Process each image found
  for (let i = 0; i < images.length; i++) {
    const image = images[i];

