      imageData = typeof image.data === 'string' 
        ? `data:${mimeType};base64,${image.data}`
        : image.data;
    }

    processedImages.push({
      index: i,
      data: imageData,
      mimeType: mimeType,
      filename: `headshot_${userName.replace(/\s+/g, '_')}_${i + 1}.png`
    });
  }

  // Create output object
  processedItems.push({
    json: {
      processed_images: processedImages,
