  const planType = userData['Plan Type'] || userData.plan_type || '';
  const isPro = planType.toLowerCase() === 'pro';

  if (isPro) {
    // Pro users always allowed, no quota checks
    outputItems.push({
      json: {
        allowed: true,
        is_pro: true,
        reason: 'Pro plan - unlimited access',
        email: userEmail,
        user_id: userData.id,
        plan_type: planType,
        original_data: data
      }
    });
    continue;
  }

  // For non-Pro users, check quotas
  // Get current date and user's last reset date
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  // Use correct Airtable field names
  let lastResetDate = userData['Current Month'] ? new Date(userData['Current Month']) : null;
  let headshotsUsed = parseInt(userData['Headshots Used This Month']) || 0;
  let postsUsed = parseInt(userData['Posts Generated This Month']) || 0;

  // Check if we need to reset monthly limits
  let needsReset = false;
  if (!lastResetDate) {
    needsReset = true;
  } else {
    const lastResetMonth = lastResetDate.getMonth();
    const lastResetYear = lastResetDate.getFullYear();

    if (currentYear > lastResetYear || (currentYear === lastResetYear && currentMonth > lastResetMonth)) {
      needsReset = true;
    }
  }

  // Reset counters if needed
  if (needsReset) {
    headshotsUsed = 0;
    postsUsed = 0;
  }

  // CRITICAL FIX: Get services array from webhook body and normalize it HERE
  let servicesRaw = webhookBody.services || webhookBody.service_selection || webhookBody.service || [];

  // Ensure it's an array
  if (!Array.isArray(servicesRaw)) {
    servicesRaw = [servicesRaw];
  }

